<?php
declare(strict_types=1);require_once __DIR__.'/includes/ui.php';require_once __DIR__.'/includes/economy.php';pv_require_login();$db=pv_db();$uid=(int)$_SESSION['myid'];$notice='';$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){try{pv_require_csrf();$action=(string)($_POST['action']??'');if($action==='list'){dn_create_listing($db,$uid,(int)($_POST['digimon_id']??0),(int)($_POST['price']??0));$notice='Digimon listed on the exchange.';}elseif($action==='cancel'){dn_cancel_listing($db,$uid,(int)($_POST['listing_id']??0));$notice='Listing cancelled.';}elseif($action==='buy'){dn_buy_listing($db,$uid,(int)($_POST['listing_id']??0));$notice='Exchange completed. Digimon ownership transferred safely.';}}catch(Throwable $e){$error=$e->getMessage();}}
$market=dn_market_list($db);$collection=dn_collection_rows($db,$uid);$eligible=array_values(array_filter($collection,fn($d)=>empty($d['slot'])&&(int)($d['locked_trade']??0)===0));$mine=[];$stmt=$db->prepare('SELECT t.*,d.nickname,d.level,s.name species_name,s.sprite FROM trade_listings t JOIN digimon_instances d ON d.id=t.digimon_id JOIN digimon_species s ON s.id=d.species_id WHERE t.seller_id=? AND t.status="active" ORDER BY t.created_at DESC');$stmt->bind_param('i',$uid);$stmt->execute();$r=$stmt->get_result();while($x=$r->fetch_assoc())$mine[]=$x;$stmt->close();$stmt=$db->prepare('SELECT money FROM members WHERE id=?');$stmt->bind_param('i',$uid);$stmt->execute();$wallet=(int)($stmt->get_result()->fetch_assoc()['money']??0);$stmt->close();pv_page_start('Digimon Exchange','trade.php',true);?>
<div class="pv-game-layout"><?php pv_game_side_menu('trade.php');?><main class="pv-main-column"><section class="pv-page"><div class="pv-page-head"><?php nxt_page_sprites();?><div><span class="pv-eyebrow">TAMER NETWORK / PARTNER EXCHANGE</span><h1>Digimon Exchange</h1><p class="pv-subtle">List collection Digimon for Bits. Active party members cannot be listed; listed Digimon are reserved until sold or cancelled.</p></div><div class="pv-wallet">BITS <strong><?=number_format($wallet)?></strong></div></div><?php if($notice):?><div class="pv-flash success"><?=pv_h($notice)?></div><?php endif;?><?php if($error):?><div class="pv-flash error"><?=pv_h($error)?></div><?php endif;?><section class="pv-card" style="padding:18px"><h2>Create listing</h2><?php if($eligible):?><form method="post" class="pv-grid cols-3"><?=pv_csrf_field()?><input type="hidden" name="action" value="list"><div class="pv-field"><label>Digimon</label><select name="digimon_id"><?php foreach($eligible as $d):?><option value="<?=(int)$d['id']?>"><?=pv_h((string)($d['nickname']?:$d['name']))?> · Lv. <?=(int)$d['level']?></option><?php endforeach;?></select></div><div class="pv-field"><label>Price (Bits)</label><input type="number" name="price" min="1" max="999999999" value="1000" required></div><div class="pv-field"><label>&nbsp;</label><button class="pv-button">List Digimon</button></div></form><?php else:?><div class="pv-empty">No unassigned, unlocked Digimon are available to list.</div><?php endif;?></section><?php if($mine):?><section class="pv-card" style="padding:18px;margin-top:14px"><h2>Your active listings</h2><div class="pv-trade-market-grid"><?php foreach($mine as $x):?><article class="pv-trade-card"><img src="<?=pv_h(pv_static((string)$x['sprite']))?>" alt=""><div><strong><?=pv_h((string)($x['nickname']?:$x['species_name']))?></strong><span>Lv. <?=(int)$x['level']?> · <?=number_format((int)$x['price'])?> Bits</span></div><form method="post"><?=pv_csrf_field()?><input type="hidden" name="listing_id" value="<?=(int)$x['id']?>"><button class="pv-button pv-button-secondary" name="action" value="cancel">Cancel</button></form></article><?php endforeach;?></div></section><?php endif;?><section class="pv-card" style="padding:18px;margin-top:14px"><h2>Live marketplace</h2><div class="pv-trade-market-grid"><?php foreach($market as $x):?><article class="pv-trade-card"><img src="<?=pv_h(pv_static((string)$x['sprite']))?>" alt=""><div class="pv-trade-card-body"><small><?=pv_h((string)$x['stage'])?> // <?=pv_h((string)$x['attribute'])?></small><h3><?=pv_h((string)($x['nickname']?:$x['species_name']))?></h3><p>Lv. <?=(int)$x['level']?> · Seller <?=pv_h((string)$x['username'])?></p><strong><?=number_format((int)$x['price'])?> Bits</strong><?php if((int)$x['seller_id']!==$uid):?><form method="post"><?=pv_csrf_field()?><input type="hidden" name="listing_id" value="<?=(int)$x['id']?>"><button class="pv-button" name="action" value="buy">Acquire</button></form><?php endif;?></div></article><?php endforeach;?></div><?php if(!$market):?><div class="pv-empty">No Digimon are currently listed.</div><?php endif;?></section></section></main></div><?php pv_page_end(); ?>
